/// The item with this protocol ID, if there is one.
pub fn item(id: i32) -> Option<&'static Item> {
    usize::try_from(id).ok().and_then(|i| ITEMS.get(i))
}

/// The name of a data component type, for reading and for reporting
/// the ones this client does not yet know how to read.
pub fn component(id: i32) -> Option<&'static str> {
    usize::try_from(id).ok().and_then(|i| COMPONENTS.get(i)).copied()
}
